  void VerifyGrids17(){
   var carry=new RaidInventory(8,6);carry.Add(ItemKind.AK,1);carry.Add(ItemKind.Armor,1);Check(carry.UsedCells==15&&carry.At(0).Kind==ItemKind.AK&&carry.At(3).Kind==ItemKind.Armor,"Carried equipment restores original multi-cell footprints");
   carry.Add(ItemKind.Medkit,2);carry.Add(ItemKind.Cola,3);Check(carry.UsedCells==19&&carry.Slots.Find(p=>p.Kind==ItemKind.Medkit).Count==2&&carry.Slots.FindAll(p=>p.Kind==ItemKind.Cola).Count==3,"Medicine stacks while collection materials remain singles");
   carry.Add(ItemKind.Ammo,180);Check(carry.Slots.FindAll(p=>p.Kind==ItemKind.Ammo).Count==2&&carry.Count(ItemKind.Ammo)==180,"Carried 180 rounds split into two stacks of 100 and 80");
   var warehouse=new RaidInventory(18,20,true);warehouse.Add(ItemKind.AK,1);warehouse.Add(ItemKind.Armor,1);warehouse.Add(ItemKind.Helmet,1);
   Check(warehouse.UsedCells==19,"Warehouse retains 3x2 weapon 3x3 armor and 2x2 helmet footprints");
   warehouse.Add(ItemKind.Ammo,301);warehouse.Add(ItemKind.Medkit,21);warehouse.Add(ItemKind.Intel,21);
   Check(warehouse.Slots.FindAll(p=>p.Kind==ItemKind.Ammo).Count==2&&warehouse.Slots.Exists(p=>p.Kind==ItemKind.Ammo&&p.Count==300),"Warehouse ammunition limit is 300");
   Check(warehouse.Slots.FindAll(p=>p.Kind==ItemKind.Medkit).Count==2&&warehouse.Slots.Exists(p=>p.Kind==ItemKind.Medkit&&p.Count==20)&&warehouse.Slots.Exists(p=>p.Kind==ItemKind.Intel&&p.Count==20),"Other warehouse supplies use stacks of 20 including gold materials");
   Check(warehouse.Clone().WarehouseMode&&warehouse.Clone().UsedCells==warehouse.UsedCells,"Cloning retains container-specific stacking and footprints");
   var legacy=new BaseSave{Version=5,StarterGranted=true,GridInitialized=true,GearGranted=true,RigGear=new ItemStack(ItemKind.StandardRig,1),PackGear=new ItemStack(ItemKind.StandardPack,1)};
   legacy.CampBag.Add(new ItemStack(ItemKind.Scrap,35,ItemOrigin.Certified){Cell=0});legacy.SafeItems.Add(new ItemStack(ItemKind.Cola,15,ItemOrigin.Certified){Cell=0});
   CampRules.Normalize(legacy);int total=legacy.Stored[(int)ItemKind.Scrap];foreach(var p in legacy.CampBag)if(p.Kind==ItemKind.Scrap)total+=p.Count;
   Check(legacy.Version==7&&legacy.CampBag.Count==20&&total==35&&legacy.Certified[(int)ItemKind.Scrap]==15,"v5 carried stacks migrate to singles and preserve certified overflow in warehouse");
   Check(legacy.SafeItems.Count==9&&legacy.Stored[(int)ItemKind.Cola]==6,"Secure box migration preserves excess items in warehouse");
   Check(legacy.CampBag.TrueForAll(p=>p.Identified)&&legacy.SafeItems.TrueForAll(p=>p.Identified),"Already owned migrated items remain identified");
  }
  void VerifyTransfers17(){
   FreshCamp();G.Chest.Slots.Clear();int cell=FindCell(ItemArea.Warehouse,ItemKind.Ammo);int count=G.ItemAt(ItemArea.Warehouse,cell).Count;int total=G.Save.Stored[0];
   Check(G.QuickTransfer(ItemArea.Warehouse,cell)&&G.Chest.Count(ItemKind.Ammo)==count&&G.Chest.Slots.TrueForAll(p=>p.Count<=100)&&G.Save.Stored[0]==total-count,"Warehouse quick transfer splits ammunition and conserves quantity");
   cell=G.Chest.Slots[0].Cell;int n=G.Chest.At(cell).Count;Check(G.QuickTransfer(ItemArea.Rig,cell)&&G.Save.Stored[0]==total-count+n,"Rig quick transfer merges into warehouse larger stacks");
   G.Chest.Slots.Clear();G.Chest.Add(ItemKind.Scrap,G.Chest.SlotCapacity);CampRules.Deposit(G.Save,ItemKind.Cola,20);cell=FindCell(ItemArea.Warehouse,ItemKind.Cola);G.Bag.Add(ItemKind.Scrap,18);
   Check(G.QuickTransfer(ItemArea.Warehouse,cell)&&G.Bag.Count(ItemKind.Cola)==2&&G.Save.Stored[(int)ItemKind.Cola]==18,"Limited backpack space keeps excess warehouse supplies in source");
   G.Bag.Slots.Clear();cell=FindCell(ItemArea.Warehouse,ItemKind.Cola);Check(G.MoveItem(ItemArea.Warehouse,cell,ItemArea.Backpack,5)&&G.Bag.Count(ItemKind.Cola)==18&&G.Bag.At(5).Kind==ItemKind.Cola,"Dragging warehouse stack splits into free carried cells starting at target");
   G.Bag.Slots.Clear();cell=FindCell(ItemArea.Warehouse,ItemKind.Armor);string id=G.ItemAt(ItemArea.Warehouse,cell).Id;
   Check(!G.MoveItem(ItemArea.Warehouse,cell,ItemArea.Backpack,19)&&G.Save.Warehouse.Exists(p=>p.Id==id),"Armor rejects an edge cell without continuous space");
   Check(G.MoveItem(ItemArea.Warehouse,cell,ItemArea.Backpack,0)&&G.Bag.At(12).Id==id&&G.Bag.UsedCells==9,"Armor occupies nine cells in backpack");
   Check(G.QuickTransfer(ItemArea.Backpack,0)&&G.Save.Warehouse.Exists(p=>p.Id==id)&&CampRules.Grid(G.Save).W(ItemKind.Armor)==3,"Returning armor restores warehouse footprint");
   int original=G.Save.Coins;cell=FindCell(ItemArea.Warehouse,ItemKind.Ammo);var ammo=G.ItemAt(ItemArea.Warehouse,cell);int price=ammo.Count*2;
   Check(G.SellWarehouse(new HashSet<string>{ammo.Id})&&G.Save.Coins==original+price,"Sale uses actual stack count and saves exact coins");
   var before=(int[])G.Save.Stored.Clone();Check(G.SortWarehouse(),"Warehouse sort supports new stacking policy");bool same=true;for(int i=0;i<before.Length;i++)same&=before[i]==G.Save.Stored[i];Check(same,"Sorting preserves quantities");
   FreshCamp();G.Bag.Add(ItemKind.Scrap,8);string path=G.SavePath;File.WriteAllText(Path.Combine(folder,"save-blocker"),"block");G.SavePath=Path.Combine(folder,"save-blocker","stash.json");int old=G.Save.Stored[(int)ItemKind.Scrap];Check(!G.QuickTransfer(ItemArea.Backpack,0)&&G.Bag.Count(ItemKind.Scrap)==8&&G.Save.Stored[(int)ItemKind.Scrap]==old,"Failed save restores split inventory transactions");G.SavePath=path;
  }
  void VerifyIdentification17(){
   LiveRaid();G.InventoryOpen=false;G.Player.transform.position=new Vector3(-6,0,-11);G.Player.Aim=Vector3.forward;G.Vision.Refresh(G.Player.transform.position,G.Player.Aim);
   var box=G.Map.AddLoot(G.Player.transform.position+Vector3.forward*.4f,"识别检查",ItemKind.Cola,1,ItemKind.Medkit,1,false);box.SearchDuration=2;
   foreach(var p in box.Items){p.Identified=false;p.RaidFound=true;}G.EnsureLootGrid(box);var input=new TouchInput{Searching=true};G.Controls=input;
   G.TickInteraction(.5f);Check(!G.InventoryOpen&&!box.Opened&&box.Search>.4f,"Holding F searches in world without opening loot screen");
   input.Searching=false;G.TickInteraction(.1f);Check(box.Search==0,"Releasing F resets incomplete opening");
   input.Searching=true;G.TickInteraction(2.01f);Check(box.Opened&&G.InventoryOpen&&G.OpenLoot==box&&box.Items.TrueForAll(p=>!p.Identified),"Completed opening enters UI with exact unknown item count");
   Check(box.Items.Count==2&&G.ItemAt(ItemArea.Loot,0)==null&&!G.QuickTransfer(ItemArea.Loot,0)&&!G.DropItem(ItemArea.Loot,0),"Unknown items cannot be inspected transferred or discarded");
   G.TickIdentification(.49f);Check(!box.Items[0].Identified&&box.IdentifyProgress>.48f,"Green item remains unknown before half a second");
   G.TickIdentification(.01f);Check(box.Items[0].Identified&&!box.Items[1].Identified,"Green completes at 0.5 seconds and next item remains unknown");
   G.TickIdentification(.6f);G.CloseInventory();Check(box.IdentifyProgress==0&&box.IdentifyingId==null&&box.Items[0].Identified&&!box.Items[1].Identified,"Closing keeps completed identifications and resets unfinished progress");
   G.TickInteraction(.01f);Check(!G.InventoryOpen,"Still-held F does not immediately reopen after close");input.Searching=false;G.TickInteraction(.01f);input.Searching=true;G.TickInteraction(.01f);
   Check(G.InventoryOpen&&box.Opened&&box.IdentifyProgress<.1f,"One new F press reopens an opened box without another search bar");
   G.TickIdentification(.9f);Check(!box.Items[1].Identified,"Blue identification starts over after reopening");G.TickIdentification(.1f);Check(box.Items[1].Identified,"Blue finishes after a fresh one second");
   Check(G.QuickTransfer(ItemArea.Loot,box.Items[0].Cell)&&G.Bag.Count(ItemKind.Cola)==1&&G.RaidGain==10,"Identified loot transfers and contributes to current raid gain");
   foreach(var kind in new[]{ItemKind.Circuit,ItemKind.Intel}){box.Items.Clear();box.Items.Add(new ItemStack(kind,1,ItemOrigin.Certified){Identified=false,Cell=0});G.ResetIdentification();float seconds=RaidGame.IdentificationSeconds(kind);G.TickIdentification(seconds-.01f);Check(!box.Items[0].Identified,"Rarity duration not prematurely completed "+kind);G.TickIdentification(.01f);Check(box.Items[0].Identified,"Rarity exact duration completed "+kind);}
   G.Paused=true;
  }
  void VerifyDrops17(){
   var random=new System.Random(77);for(int type=0;type<6;type++){bool counts=true,units=true,rarity=true;for(int i=0;i<1200;i++){var list=HarborContent.Contents((SupplyType)type,random);counts&=list.Count>=1&&list.Count<=6;foreach(var p in list){units&=p.Kind==ItemKind.Ammo?p.Count>=10&&p.Count<=30:p.Count==1;rarity&=LootBalance.Eligible((SupplyType)type,p.Kind);}}Check(counts&&units&&rarity,"Sparse container counts and stack amounts "+(SupplyType)type);}
  }
  void VerifyProtection17(){
   FreshCamp();G.Safe.Add(ItemKind.Cola,3,ItemOrigin.Certified);Check(G.Safe.UsedCells==3,"Secure consumables use single cells");
   foreach(var k in RaidInventory.AvailableGear){int c=FindCell(ItemArea.Warehouse,k);Check(!G.MoveItem(ItemArea.Warehouse,c,ItemArea.Safe,3),"Secure box rejects equipment "+k);}
   G.StartRaid();G.Finish(false);Check(G.Safe.Count(ItemKind.Cola)==3&&G.Equipped==null,"Death keeps secure single items only");
   LiveRaid();G.Bag.Add(ItemKind.Intel,1,ItemOrigin.Certified,true);G.InventoryOpen=true;Check(G.MoveItem(ItemArea.Backpack,0,ItemArea.Safe,0),"New loot enters secure container");G.CloseInventory();G.LoadSave();G.BuildCamp();Check(G.Safe.Count(ItemKind.Intel)==1&&G.Equipped==null,"Interrupted raid retains identified secure loot");
   FreshCamp();G.Bag.Add(ItemKind.Medkit,2);G.Player.Health=20;G.Panel=CampPanel.None;Check(G.UseItem(ItemArea.Backpack,0)&&G.Player.Health==65&&G.Bag.Count(ItemKind.Medkit)==1,"Single medicine use consumes exactly one unit");
  }
  void VerifyGun17(){
   LiveRaid();Check(PixelArt.Rifle.texture.width==72&&PixelArt.Rifle.texture.height==28,"World AK uses new detailed 72 by 28 side silhouette");
   for(int i=0;i<4;i++){G.Rig.ResetView(45+i*90);G.Rig.Tick(0);G.Player.Aim=Vector3.right;G.Player.Draw(G.View,0);var physical=G.Player.MuzzleOnPlane(G.View);var visual=G.Player.Gun.transform.TransformPoint(new Vector3(47f/52,0,0));Vector3 a=G.View.WorldToScreenPoint(physical),b=G.View.WorldToScreenPoint(visual);Check(Vector2.Distance(a,b)<.02f&&Mathf.Abs(physical.y-G.Player.transform.position.y-RaidGame.CombatHeight)<.001f,"Muzzle projection aligns in camera direction "+i);}
   File.WriteAllBytes(Path.Combine(folder,"handheld-ak.png"),PixelArt.Rifle.texture.EncodeToPNG());G.Paused=true;
  }
